```javascript
import events from './events.json' with {type:'json'};

const DEFAULT_PAGE_SIZE = 2;
const MAX_PAGE_SIZE = 3;
const MIN_PAGE_SIZE = 1;

function encodeCursor(offset) {
  return Buffer.from(JSON.stringify({o: offset}), 'utf8').toString('base64url');
}

function decodeCursor(cursor) {
  let parsed;
  try {
    const json = Buffer.from(cursor, 'base64url').toString('utf8');
    parsed = JSON.parse(json);
  } catch (e) {
    throw new Error('Unknown cursor');
  }
  if (!parsed || typeof parsed !== 'object' || !('o' in parsed) || typeof parsed.o !== 'number' || !Number.isInteger(parsed.o)) {
    throw new Error('Unknown cursor');
  }
  return parsed.o;
}

const eventsListInputSchema = {
  type: 'object',
  properties: {
    cursor: { type: 'string' },
    page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE }
  },
  required: [],
  additionalProperties: false
};

export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events with optional cursor pagination and page_size (1-3, default 2).',
      inputSchema: eventsListInputSchema
    }
  ];
}

function validateEventsListArgs(args) {
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error('Unknown field: ' + key);
    }
  }
  let cursor = undefined;
  if ('cursor' in args) {
    if (typeof args.cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
    if (args.cursor.length === 0) {
      throw new Error('Unknown cursor');
    }
    cursor = args.cursor;
  }
  let pageSize = DEFAULT_PAGE_SIZE;
  if ('page_size' in args) {
    const ps = args.page_size;
    if (typeof ps !== 'number' || !Number.isInteger(ps) || ps < MIN_PAGE_SIZE || ps > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer between 1 and 3');
    }
    pageSize = ps;
  }
  return { cursor, pageSize };
}

export async function callTool(name, args = {}) {
  if (name !== 'events_list') {
    throw new Error('Unknown tool: ' + name);
  }
  const { cursor, pageSize } = validateEventsListArgs(args);
  let offset = 0;
  if (cursor !== undefined) {
    offset = decodeCursor(cursor);
    if (offset < 0 || offset >= events.length) {
      throw new Error('Unknown cursor');
    }
  }
  const slice = events.slice(offset, offset + pageSize);
  const nextOffset = offset + pageSize;
  const result = {
    events: slice,
    next_cursor: nextOffset < events.length ? encodeCursor(nextOffset) : null
  };
  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}
```

