{"content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { callTool, listTools } from './server.mjs';

function parse(r) {
  return JSON.parse(r.content[0].text);
}

test('listTools exposes events_list with strict schema', async () => {
  const tools = await listTools();
  assert.equal(tools.length, 1);
  assert.equal(tools[0].name, 'events_list');
  assert.equal(tools[0].inputSchema.additionalProperties, false);
  assert.equal(tools[0].inputSchema.type, 'object');
});

test('first page default size 2', async () => {
  const r = await callTool('events_list', {});
  const data = parse(r);
  assert.deepEqual(data.events.map(e => e.id), ['e1', 'e2']);
  assert.equal(typeof data.next_cursor, 'string');
});

test('next page via cursor preserves order', async () => {
  const r1 = await callTool('events_list', {});
  const data1 = parse(r1);
  const r2 = await callTool('events_list', { cursor: data1.next_cursor });
  const data2 = parse(r2);
  assert.deepEqual(data2.events.map(e => e.id), ['e3', 'e4']);
  assert.equal(data2.next_cursor, null);
});

test('page_size = 3 returns three and next cursor', async () => {
  const r = await callTool('events_list', { page_size: 3 });
  const data = parse(r);
  assert.deepEqual(data.events.map(e => e.id), ['e1', 'e2', 'e3']);
  assert.equal(typeof data.next_cursor, 'string');
});

test('page_size = 1 paginates one at a time', async () => {
  const r1 = await callTool('events_list', { page_size: 1 });
  const d1 = parse(r1);
  assert.deepEqual(d1.events.map(e => e.id), ['e1']);
  const r2 = await callTool('events_list', { page_size: 1, cursor: d1.next_cursor });
  const d2 = parse(r2);
  assert.deepEqual(d2.events.map(e => e.id), ['e2']);
});

test('reject page_size out of range', async () => {
  await assert.rejects(() => callTool('events_list', { page_size: 0 }));
  await assert.rejects(() => callTool('events_list', { page_size: 4 }));
  await assert.rejects(() => callTool('events_list', { page_size: 1.5 }));
});

test('reject non-integer and non-string types', async () => {
  await assert.rejects(() => callTool('events_list', { page_size: '2' }));
  await assert.rejects(() => callTool('events_list', { cursor: 123 }));
});

test('reject unknown cursor', async () => {
  await assert.rejects(() => callTool('events_list', { cursor: 'garbage' }));
  await assert.rejects(() => callTool('events_list', { cursor: '!!!notbase64!!!' }));
});

test('reject extra fields', async () => {
  await assert.rejects(() => callTool('events_list', { foo: 'bar' }));
});

test('reject unknown tool', async () => {
  await assert.rejects(() => callTool('nope', {}));
});
